def findRepeatedDnaSequences(s: str) -> list[str]:
    if len(s) < 10: return []
    mapping = {'A': 0, 'C': 1, 'G': 2, 'T': 3}
    seen = set()
    repeated = set()
    mask = 0
    for i in range(9):
        mask = (mask << 2) | mapping[s[i]]
    for i in range(9, len(s)):
        mask = ((mask << 2) & 0xFFFFF) | mapping[s[i]]
        sub = s[i - 9:i + 1]
        if mask in seen:
            repeated.add(sub)
        else:
            seen.add(mask)
    return sorted(list(repeated))

